    static fastSin(deg) {
        let idx = Math.floor(deg * 10) % 3600;
        if (idx < 0) idx += 3600;
        return MatrixMathTables.SIN_DEG_TABLE[idx];
    }

    static fastCos(deg) {
        let idx = Math.floor(deg * 10) % 3600;
        if (idx < 0) idx += 3600;
        return MatrixMathTables.COS_DEG_TABLE[idx];
    }

